function dbToAmp(db){ return Math.pow(10, db/20); }
function ampToDb(a){ return a>0? 20*Math.log10(a) : -Infinity; }
function r1(x){
  if(x===-Infinity) return -Infinity;
  if(x==null||!isFinite(x)) return null;
  return Math.round(x*100)/100;
}
function analyzeLoudness(samples, sr, opts){
  opts=opts||{};
  var n=samples? samples.length:0;
  if(!n||!sr||sr<=0) return {error:'缺少采样数据'};
  var peak=0, sum=0, dc=0;
  for(var i=0;i<n;i++){
    var s=samples[i], ab=Math.abs(s);
    if(ab>peak)peak=ab;
    sum+=s*s; dc+=s;
  }
  dc/=n;
  var rms=Math.sqrt(sum/n);
  var clipped=0;
  for(var i2=0;i2<n;i2++){ if(Math.abs(samples[i2])>=0.99999) clipped++; }
  var blockLen=Math.max(1, Math.floor(sr*0.4));
  var hop=Math.max(1, Math.floor(sr*0.1));
  var blocks=[];
  for(var st=0; st+blockLen<=n; st+=hop){
    var bs=0;
    for(var j=st;j<st+blockLen;j++){ bs+=samples[j]*samples[j]; }
    blocks.push({ms:bs/blockLen});
  }
  function loudOf(ms){ return -0.691+10*Math.log10(ms>0?ms:1e-12); }
  blocks.forEach(function(b){ b.lufs=loudOf(b.ms); });
  var kept=blocks.filter(function(b){ return b.lufs>-70; });
  function integrate(list){
    if(!list.length) return null;
    var s=0;
    list.forEach(function(b){ s+=b.ms; });
    return loudOf(s/list.length);
  }
  var firstPass=integrate(kept);
  var kept2=kept;
  if(firstPass!=null){
    var gate=firstPass-10;
    kept2=kept.filter(function(b){ return b.lufs>gate; });
  }
  var integrated=integrate(kept2);
  var target=(typeof opts.targetLufs==='number')?opts.targetLufs:-14;
  var gain=(integrated==null)?null:Math.round((target-integrated)*100)/100;
  var maxGain=(peak>0)?ampToDb(1/peak):null;
  return {
    peak:Math.round(peak*1e6)/1e6, peakDb:r1(ampToDb(peak)),
    rms:Math.round(rms*1e6)/1e6, rmsDb:r1(ampToDb(rms)),
    lufsApprox:r1(integrated), dcOffset:Math.round(dc*1e6)/1e6,
    clipped:clipped, blocks:blocks.length, blocksKept:kept2.length,
    targetLufs:target, suggestedGainDb:gain,
    maxGainBeforeClipDb:r1(maxGain),
    gainClipped:(gain!=null&&maxGain!=null&&gain>maxGain),
    silent:integrated==null,
    warning:clipped>0? ('检测到 '+clipped+' 个采样达到或超过满幅（0 dBFS），可能已削波'):null
  };
}
var EXPORTS={dbToAmp:dbToAmp, ampToDb:ampToDb, analyzeLoudness:analyzeLoudness};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LoudnessForgePure = EXPORTS; }
